-- JujuyConecta - esquema inicial alineado con JujuyDbContext de V4.
-- Ejecutar UNA sola vez en Supabase SQL Editor, únicamente si NO se usará
-- dotnet ef database update para la creación inicial.
-- IMPORTANTE: no contiene credenciales ni datos reales.
BEGIN;

CREATE TABLE IF NOT EXISTS public.events (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" varchar(180) NOT NULL,
    "Location" varchar(300) NOT NULL,
    "StartsAtUtc" timestamptz NOT NULL,
    "DurationMinutes" integer NOT NULL,
    "Published" boolean NOT NULL,
    "IsDemo" boolean NOT NULL,
    CONSTRAINT ck_events_duration_positive CHECK ("DurationMinutes" > 0)
);

CREATE TABLE IF NOT EXISTS public.attendance_reminders (
    "Id" uuid PRIMARY KEY,
    "EventId" bigint NOT NULL,
    "Email" varchar(254) NOT NULL,
    "EmailNormalized" varchar(254) NOT NULL,
    "ReminderConsent" boolean NOT NULL,
    "NewsConsent" boolean NOT NULL,
    "CreatedAtUtc" timestamptz NOT NULL,
    "ReminderDueAtUtc" timestamptz NOT NULL,
    "Status" varchar(24) NOT NULL,
    "LockedUntilUtc" timestamptz NULL,
    "NextAttemptAtUtc" timestamptz NULL,
    "SentAtUtc" timestamptz NULL,
    "Attempts" integer NOT NULL,
    CONSTRAINT fk_attendance_reminders_events_eventid FOREIGN KEY ("EventId") REFERENCES public.events("Id") ON DELETE RESTRICT,
    CONSTRAINT ck_reminders_attempts_nonnegative CHECK ("Attempts" >= 0),
    CONSTRAINT ck_reminders_status CHECK ("Status" IN ('Pending', 'Processing', 'Sent', 'Failed', 'Cancelled'))
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_attendance_reminders_eventid_emailnormalized
    ON public.attendance_reminders ("EventId", "EmailNormalized");
CREATE INDEX IF NOT EXISTS ix_attendance_reminders_status_reminderdueatutc
    ON public.attendance_reminders ("Status", "ReminderDueAtUtc");

-- El frontend NO debe leer correos de asistentes usando la API pública de Supabase.
-- Se mantienen sin políticas para los roles anon/authenticated; el backend usa
-- una conexión de servidor a PostgreSQL con secretos fuera del navegador.
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.attendance_reminders ENABLE ROW LEVEL SECURITY;

COMMIT;
